from pathlib import Path
from html import escape
import json
root=Path('artifacts/chapter-one-followup');m=json.loads(Path('releases/chapter-package.json').read_text());n=json.loads((root/'natural-evidence.json').read_text());q=json.loads((root/'qa-evidence.json').read_text());c=json.loads((root/'content-mapping.json').read_text());t=json.loads((root/'taptap-receipt.json').read_text())
