 items+=f'<details><summary>{names[item["id"]]} · 三态短句与代表互动</summary><div class="three">'+''.join(shot(s['screenshot'],s['text']) for s in item['states'])+'</div><p>'+escape(item['action']+'：'+item['reply'])+'</p>'+movie(item['video'],'QA实际清理、原耗时升级、免费互动 · 自然1倍')+'</details>'
